arguments.new_str:
using Microsoft.Extensions.ML;
using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);

// Train the model before building the host so the file exists for the pool
var trainer = new ModelTrainingService(
    LoggerFactory.Create(b => b.AddConsole())
        .CreateLogger<ModelTrainingService>());
trainer.TrainAndSave();

// Register the thread-safe pooled prediction engine
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainer.ModelPath);

var app = builder.Build();

string[] categories = ["Billing", "General", "Technical"];

app.MapPost("/api/ticket/classify", (
    [FromBody] TicketRequest request,
    PredictionEnginePool<TicketInput, TicketPrediction> pool) =>
{
    if (request.Priority is < 1 or > 3)
        return Results.BadRequest("Priority must be between 1 and 3.");

    var input = new TicketInput
    {
        Subject = request.Subject,
        Description = request.Description,
        Priority = request.Priority,
    };

    var prediction = pool.Predict(input);

    var confidence = new Dictionary<string, float>();
    for (var i = 0; i < categories.Length && i < prediction.Score.Length; i++)
        confidence[categories[i]] = prediction.Score[i];

    return Results.Ok(new TicketResponse
    {
        PredictedCategory = prediction.PredictedCategory,
        Confidence = confidence,
    });
});

app.Run();

